test('overdueInvoices returns empty array for no invoices', () => {
  const result = overdueInvoices([], '2026-10-31');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no invoices are overdue', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      number: 'INV-2026-0001',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = overdueInvoices(invoices, '2026-10-31');
  assert.deepEqual(result, []);
});

