      status: 'issued',
      number: 'INV-2026-0001',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 50000, vatRate: 0, discountPercent: 0 }],
    },
    {
      customerId: 'C-001',
      issueDate: '2026-10-08',
      dueDate: '2026-11-07',
      status: 'partially_paid',
      number: 'INV-2026-0002',
      lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 30000, vatRate: 0, discountPercent: 0 }],
      payments: [{ amount: 10000, date: '2026-10-20' }],
    },
    {
      customerId: 'C-002',
      issueDate: '2026-10-09',
      dueDate: '2026-11-08',
      status: 'issued',
      number: 'INV-2026-0003',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 40000, vatRate: 0, discountPercent: 0 }],
    },
    {
      customerId: 'C-003',
      issueDate: '2026-10-10',
      dueDate: '2026-11-09',
      status: 'draft',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 100000, vatRate: 0, discountPercent: 0 }],
    },
    {
      customerId: 'C-004',
      issueDate: '2026-10-11',
      dueDate: '2026-11-10',
      status: 'paid',
      number: 'INV-2026-0004',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 25000, vatRate: 0, discountPercent: 0 }],
      payments: [{ amount: 25000, date: '2026-10-20' }],
