  // Outstanding: C-001 (50000 + 20000) + C-002 (40000) = 110000
  assert.equal(result.outstanding, 110000);

  // Overdue: only INV-2026-0001 (dueDate 2026-10-15)
  assert.equal(result.overdue.count, 1);
  assert.equal(result.overdue.amount, 50000);

  // Top customers: C-001 (70000), C-002 (40000)
  assert.equal(result.topCustomers.length, 2);
  assert.equal(result.topCustomers[0].customerId, 'C-001');
  assert.equal(result.topCustomers[0].due, 70000);
  assert.equal(result.topCustomers[1].customerId, 'C-002');
  assert.equal(result.topCustomers[1].due, 40000);
});

